export const RELATIONAL_BINDINGS_SQL=`WITH event_rows AS MATERIALIZED (
 SELECT e.event_id,to_jsonb(e) AS document FROM proof_indexer.events e
 JOIN proof_indexer.transactions t ON t.network=e.network AND t.txid=e.txid AND t.status='confirmed' AND t.block_height=e.block_height
 JOIN proof_indexer.blocks b ON b.network=t.network AND b.height=t.block_height AND b.block_hash=t.block_hash AND b.canonical=true
 WHERE e.network='livenet' AND e.status='confirmed' AND e.block_height=$1 AND t.block_hash=$2 AND e.protocol=ANY(ARRAY['pwm1','pwa1','pwid1','pwdns1','pwb1','pwt1','pwc1']::text[])
),record_rows AS MATERIALIZED (
 SELECT t.block_index,r.txid,to_jsonb(r) AS document FROM proof_indexer.op_returns r
 JOIN proof_indexer.transactions t ON t.network=r.network AND t.txid=r.txid
 JOIN proof_indexer.blocks b ON b.network=t.network AND b.height=t.block_height AND b.block_hash=t.block_hash AND b.canonical=true
 WHERE t.network='livenet' AND t.status='confirmed' AND t.block_height=$1 AND t.block_hash=$2 AND r.protocol=ANY(ARRAY['pwm1','pwa1','pwid1','pwdns1','pwb1','pwt1','pwc1']::text[])
) SELECT (SELECT count(*)::int FROM event_rows) AS "eventCount",
 (SELECT encode(sha256(jsonb_send(COALESCE(jsonb_agg(document ORDER BY event_id),'[]'::jsonb))),'hex') FROM event_rows) AS "eventRowsSha256",
 (SELECT count(*)::int FROM record_rows) AS "recordCount",
 (SELECT encode(sha256(jsonb_send(COALESCE(jsonb_agg(document ORDER BY block_index,txid COLLATE "C",document::text COLLATE "C"),'[]'::jsonb))),'hex') FROM record_rows) AS "recordRowsSha256"`;
